// delaytest replicates AndroidLibXrayLite's MeasureOutboundDelay so CI can
// check that configs generated by the app load in Xray and actually connect.
package main

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"sync"
	"time"

	corenet "github.com/xtls/xray-core/common/net"
	"github.com/xtls/xray-core/common/serial"
	core "github.com/xtls/xray-core/core"
	coreserial "github.com/xtls/xray-core/infra/conf/serial"
	_ "github.com/xtls/xray-core/main/distro/all"
)

var loadOnly bool

func measure(content, url string) (int64, error) {
	config, err := coreserial.LoadJSONConfig(strings.NewReader(content))
	if err != nil {
		return -1, fmt.Errorf("config load error: %w", err)
	}
	config.Inbound = nil
	var essential []*serial.TypedMessage
	for _, app := range config.App {
		if app.Type == "xray.app.proxyman.OutboundConfig" || app.Type == "xray.app.dispatcher.Config" || app.Type == "xray.app.log.Config" {
			essential = append(essential, app)
		}
	}
	config.App = essential
	inst, err := core.New(config)
	if err != nil {
		return -1, fmt.Errorf("instance creation failed: %w", err)
	}
	if loadOnly {
		inst.Close()
		return 1, nil
	}
	if err := inst.Start(); err != nil {
		return -1, fmt.Errorf("startup failed: %w", err)
	}
	defer inst.Close()
	tr := &http.Transport{
		TLSHandshakeTimeout: 6 * time.Second,
		DialContext: func(ctx context.Context, network, addr string) (net.Conn, error) {
			dest, err := corenet.ParseDestination(fmt.Sprintf("%s:%s", network, addr))
			if err != nil {
				return nil, err
			}
			return core.Dial(ctx, inst, dest)
		},
	}
	defer tr.CloseIdleConnections()
	client := &http.Client{Transport: tr, Timeout: 12 * time.Second}
	start := time.Now()
	resp, err := client.Get(url)
	if err != nil {
		return -1, err
	}
	resp.Body.Close()
	if resp.StatusCode != 204 && resp.StatusCode != 200 {
		return -1, errors.New(resp.Status)
	}
	return time.Since(start).Milliseconds(), nil
}

type result struct {
	File  string `json:"file"`
	Delay int64  `json:"delay"`
	Error string `json:"error,omitempty"`
}

func main() {
	dir, url := os.Args[1], "https://www.gstatic.com/generate_204"
	loadOnly = len(os.Args) > 2 && os.Args[2] == "load"
	files, _ := filepath.Glob(filepath.Join(dir, "*.json"))
	sort.Strings(files)
	results := make([]result, len(files))
	sem := make(chan struct{}, 24)
	var wg sync.WaitGroup
	for i, f := range files {
		wg.Add(1)
		go func(i int, f string) {
			defer wg.Done()
			sem <- struct{}{}
			defer func() { <-sem }()
			defer func() {
				if p := recover(); p != nil {
					results[i] = result{File: filepath.Base(f), Delay: -1, Error: fmt.Sprintf("PANIC: %v", p)}
				}
			}()
			b, _ := os.ReadFile(f)
			d, err := measure(string(b), url)
			r := result{File: filepath.Base(f), Delay: d}
			if err != nil {
				r.Error = err.Error()
				if len(r.Error) > 300 {
					r.Error = r.Error[:300]
				}
			}
			results[i] = r
		}(i, f)
	}
	wg.Wait()
	ok, loadErr := 0, 0
	for _, r := range results {
		if r.Delay > 0 {
			ok++
		}
		if strings.Contains(r.Error, "config load") || strings.Contains(r.Error, "instance creation") || strings.Contains(r.Error, "startup failed") {
			loadErr++
		}
	}
	out, _ := json.MarshalIndent(results, "", " ")
	os.WriteFile(filepath.Join(filepath.Dir(dir), filepath.Base(dir)+"_results.json"), out, 0644)
	fmt.Printf("total=%d ok=%d config_errors=%d\n", len(results), ok, loadErr)
}
